   DELIMITER //

   CREATE TRIGGER update_AlarmHistory_actions
     AFTER INSERT, UPDATE, DELETE ON AlarmHistory
     FOR EACH ROW
     BEGIN
       IF (NEW.HistoryAction IS NOT NULL) THEN
         -- Insertions
         IF (NEW.HistoryAction <> OLD.HistoryAction) AND (OLD.HistoryAction IS NULL) THEN
           SET NEW.ActionTimestamp = NOW();
           SET NEW.ActionType = 'I';
         END IF;
       ELSE
         -- Updates: bestimmen des maximalen Update-Eintrags
         DECLARE max_timestamp TIMESTAMP;
         DECLARE max_id INT;
         DECLARE update_action RECORD;

         SET max_timestamp = (SELECT MAX(timestamp) FROM (
             SELECT timestamp FROM AlarmHistory WHERE id = OLD.id GROUP BY id ORDER BY timestamp DESC LIMIT 1
           ) tmp);
         SET max_id = OLD.id;

         SET @max_TS := CONCAT("'", FORMAT(max_timestamp, '%Y-%m-%d %H:%i:%s'), "'");
         SET @max_ID := CONCAT("'", max_id, "'");

         PREPARE stmt FROM "SELECT ActionType, ActionTimestamp FROM AlarmHistory WHERE id = ? AND ActionTimestamp = (SELECT MAX(ActionTimestamp) FROM AlarmHistory WHERE id = ? )";
