response:
```
using System;

namespace PhotonenEnergieUndPlanckscheKonstante
{
    class Program
    {
        static void Main(string[] args)
        {
            // Variablen hinzufügen aus Tabelle
            double wavelength = 600 * Math.Pow(10, -9); // nm in Meter umrechnen
            double speedOfLight = 299792458;
            double plancksKonstante = 6.62607004 * Math.Pow(10, -34);

            // Energie eines Photons berechnen
            double photonEnergy = (plancksKonstante * speedOfLight) / wavelength;

            // Plancksche Konstante berechnen
            double h = photonEnergy / speedOfLight;

            // Ausgabe
            Console.WriteLine("Der Wert der Planckschen Konstante (h) lautet: " + h.ToString() + " J s");
            Console.WriteLine("Die Energie eines Photons mit einer Wellenlänge von 600 nm lautet: " + photonEnergy.ToString() + " J");

            // Anmerkung: Um die Plancksche Konstante (h) im Einheitenformat J s anzuzeigen, musste das Julansprodukt von h und der Lichtgeschwindigkeit umgewandelt werden.
            //           Die Formel: J s = kg m²/s entspricht J/(kg m/s) = J/s (Joule pro Sekunde = Watt)
            //           Damit ergibt sich: h J s = h J / (speedOfLight kg/m s) = h J s^-1 / (speedOfLight m/s) = h J / (speedOfLight m s^-1)
            //           Rechnung: h J / (speedOfLight m s^-1) = h * (1 kg/1 kg) * (1 m^2/1 m^2) / (speedOfLight m s^-1) = h * (1 kg m²)/(1 kg m s) = h
        }
