      @Stage(name = "Invoice Management", description = "Integration tests for Invoice Management service")

      @UseDataProvider("provideTestCases")
      public class InvoiceManagementTestStage extends AbstractGaugeStage {

          @DataProvider(name = "provideTestCases")
          public static List<List<Object>> provideTestCases() {
              return Arrays.asList(
