                  Arrays.asList("001", "existing_customer_name", 50.00, LocalDateTime.of(2022, 8, 12, 10, 30, 0))
              );
          }

          @Story(
              title = "Create Invoice for Existing Customer",
              description = "Verifies the creation of invoices for existing customers",
              tags = {"InvoiceManagement", "IntegrationTests"}
          )
          public void createInvoiceForExistingCustomer(String invoiceNumber, String customerName, double invoiceAmount, LocalDateTime invoiceDate) {
              InvoiceManagementApplication.builder()
                  .ebsOracleConnection(OracleConnectionProvider.oracleConnection())
                  .ebsUsername("your_EBS_username")
                  .ebsPassword("your_EBS_password")
                  .ebsUrl("your_EBS_URL")
                  .build()
                  .run();

              // Arrange - Configuring the test environment
              Gauge.writeSystemProperty("s3_bucket", "your_s3_bucket_name");
              Gauge.writeSystemProperty("faker_json_path", "your/fake_data/json/path");

              // Act - Invoking spring REST Endpoints
              HttpClient client = HttpClient.newHttpClient();
              String jsonInput =(new ObjectMapper()).readValue(classpathResource("input_invoice.json"), Map.class).toString();
              HttpResponse<String> response = client.send(HttpRequest.newBuilder(URI.create("http://localhost:8080/invoices"))
                      .POST(HttpRequest.BodyPublishers.ofString(jsonInput)).header("Content-Type", "application/json").build(),
                      HttpResponse.BodyHandlers.ofString());

              // Assert - Validating the response
              Map<String, String> assertAgainstEndPoint = new ObjectMapper().readValue(response.body(), Map.class);
              org.assertj.core.api.Assertions.assertThat(assertAgainstEndPoint.get("invoice_number")).isEqualTo(invoiceNumber);
              org.assertj.core.api.Assertions.assertThat(assertAgainstEndPoint.get("customer_name")).isEqualTo(customerName);
              org.assertj.core.api.Assertions.assertThat(assertAgainstEndDate).isEqualTo(invoiceDate);
          }
      }
      ```

