      ```java
      package invoice.management.stepdefs;

      import io.gauge.Context;
      import io.gauge.Step;
      import io.gauge.StepArgumentError;
      import org.junit.Assert;

      import com.github.javafaker.Faker;

      // Diese Klasse enthält die Stepdefinitions

      // Stepdefinition für 'Given an invoice with valid data'
      @Step("Given an invoice with valid data")
      public class GivenAnInvoiceWithValidDataStepDef extends AbstractStepDefinition {

         @Override
         public void execute(Context context) {
             Faker faker = new Faker();
             context.set("invoice", Invoice.builder()
                    .withCustomerName(faker.company().name())
                    .withCompanyId(1)
                    .withInvoiceNumber(faker.regexify("[A-Z0-9]{10}"))// Beispiel für ein gültiges Rechnungsnummerformat
                    .withAmount(faker.number().randomDouble(2, 0, 10000))
                    .build());
         }
      }

      // Stepdefinition für 'When I submit the invoice via POST request to "/invoices"'
      @Step("When I submit the invoice via POST request to '/invoices'")
      public class WhenSubmitInvoiceStepDef extends AbstractStepDefinition {

         @Autowired
         private InvoiceClient invoiceClient;

         @Override
         public void execute(Context context) {
             Invoice invoice = context.get("invoice");
             String jsonBody = mapper.writeValueAsString(invoice);
             RestTemplate restTemplate = new RestTemplate();
             String url = "http://localhost:8080/invoices";
             ResponseEntity<String> responseEntity = restTemplate.postForEntity(url, new HttpEntity<>(jsonBody), String.class);
             context.set("responseEntity", responseEntity);
         }
      }

      // Stepdefinition für 'Then the invoice creation is successful'
      @Step("Then the invoice creation is successful")
      public class ThenTheInvoiceCreationIsSuccessfulStepDef extends AbstractStepDefinition {

         private ResponseEntity<String> responseEntity;

         @Autowired
         private InvoiceVerifier invoiceVerifier;

         @Override
         public void execute(Context context) {
             responseEntity = context.get("responseEntity");
             Assert.assertEquals(200, responseEntity.getStatusCodeValue());
             String responseBody = responseEntity.getBody();
             Assert.assertTrue(responseBody.contains("InvoiceCreated Successfully"));
             Assert.assertTrue(invoiceVerifier.isInvoiceExists(responseEntity.getBody()));
         }
      }

      // Stepdefinition für 'And verify the invoice data inserted in the database'
      @Step("And verify the invoice data inserted in the database")
      public class AndVerifyTheInvoiceDataInsertedInDatabaseStepDef extends AbstractStepDefinition {

         private ResponseEntity<String> responseEntity;

         @Autowired
         private InvoiceVerifier invoiceVerifier;

         @Override
         public void execute(Context context) {
             responseEntity = context.get("responseEntity");
             Invoice verifiedInvoice = invoiceVerifier.verifyInvoiceDetails(responseEntity.getBody());
             Assert.assertEquals(context.get("invoice").getCustomerName(), verifiedInvoice.getCustomerName());
             Assert.assertEquals((long) context.get("invoice").getCompanyId(), verifiedInvoice.getCompanyId());
             Assert.assertEquals(context.get("invoice").getInvoiceNumber(), verifiedInvoice.getInvoiceNumber());
             Assert.assertEquals(context.get("invoice").getAmount(), verifiedInvoice.getAmount(),
                     Double.eps());
         }
      }

      private abstract class AbstractStepDefinition {

         @Context
         private Context context;

         @Autowired
         private ObjectMapper mapper;

         @Autowired
         private InvoiceClient invoiceClient;

         @Autowired
         private InvoiceVerifier invoiceVerifier;
      }
