        server.expect(MockRestRequestMatchers.methodAndUri(HttpHeaders.POST, "/invoices"))
            .andExpect(MockRestRequestMatchers.content().json(invoicePayload))
            .andRespond(MockRestResponseCreators.withStatus(HttpStatus.CREATED.value())
                .header(HttpHeaders.LOCATION, "/invoices/{id}")
                .build());

        final Map<String, Object> createdInvoice = executeInvoiceCreation();
        server.verify();

        verifyCreatedInvoiceInOracleEbs(mockOracleEbs, createdInvoice);
