    private Map<String, Object> executeInvoiceCreation() {
        final Map<String, Object> createdInvoice = rest.postForObject(
            URI.create("http://localhost:8080/invoices"), createInvoicePayload(), Map.class);
        Assert.assertNotNull(createdInvoice);
        Assert.assertThat(createdInvoice, notNullValue());
        return createdInvoice;
