    private void verifyCreatedInvoiceInOracleEbs(OEMockDataSource mockOracleEbs, Map<String, Object> createdInvoice) {
        final String customerId = MapUtils.getString(createdInvoice, "customerId");
        final String invoiceDate = MapUtils.getString(createdInvoice, "invoiceDate");

        final String expectedQuery = "SELECT * " +
            "FROM ar_invoices " +
            "WHERE customer_id = :customerId " +
            "AND invoice_date = :invoiceDate";

        final Map<String, Object> expectedParameters = Map.of(
            "customerId", customerId,
            "invoiceDate", invoiceDate
        );
        Assert.assertEquals(expectedQuery, mockOracleEbs.getLastQuery());
        Assert.assertEquals(expectedParameters, mockOracleEbs.getLastParameters());

        final List<Map<String, Object>> oracleEbsResultSet = mockOracleEbs.query(expectedQuery, expectedParameters);
        Assert.assertThat(oracleEbsResultSet, notEmptyOrNullValue());

        final Map<String, Object> oracleEbsInvoice = oracleEbsResultSet.get(0);
        Assert.assertEquals(MapUtils.getString(createdInvoice, "invoiceAmount"), oracleEbsInvoice.get("amount"));
    }

