3. Erstellen eines Datenquellenbeispiels für Oracle EBS, welches eine Mocked-Datenbank zum Testen enthält:

```java
import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class OEMockDataSource extends MysqlDataSource {

    private Connection connection;
    private String lastQuery;
    private Map<String, Object> lastParameters;

    public OEMockDataSource() {
        setName("Data Source for Oracle EBS Mock");
        // Replace with your own Oracle EBS connection properties
        setUrl("jdbc:mysql://localhost:3306/oracle_ebs_mock");
        setUsername("root");
        setPassword("root");

        setHikariConfig(new HikariConfig() {{
            setDataSource(this);
            setMinimumIdle(1);
            setMaximumPoolSize(5);
        }});

        setConnectionClassName("com.mysql.jdbc.jdbc2.optional.MysqlDataSource");
        setAllowEmptyPasswords(true);
        setServerTimezone("UTC");
    }

    @Override
    public synchronized Connection getConnection() throws SQLException {
        connection = super.getConnection();
        return connection;
    }

    public List<Map<String, Object>> query(String query, Map<String, Object> params) throws SQLException {
        PreparedStatement preparedStatement = connection.prepareStatement(query);
        applyParameters(preparedStatement, params);
        final List<Map<String, Object>> resultSet = connection.unwrap(jdbc2.optional.Jdbc2OptionalExtension.class)
            .createResultSet(preparedStatement.executeQuery()).convert Maps();
        preparedStatement.close();
        return resultSet;
    }

    public String getLastQuery() {
        return lastQuery;
    }

    public Map<String, Object> getLastParameters() {
        return lastParameters;
    }

    private void applyParameters(PreparedStatement ps, Map<String, Object> parameters) throws SQLException {
        int parameterIndex = 1;
        for (Map.Entry<String, Object> entry : parameters.entrySet()) {
            final Object parameterValue = entry.getValue();
            if (parameterValue instanceof Number) {
                ps.setObject(parameterIndex, parameterValue);
            } else if (parameterValue instanceof String) {
                ps.setString(parameterIndex, (String) parameterValue);
            } else if (parameterValue instanceof LocalDate) {
                ps.setDate(parameterIndex, java.sql.Date.valueOf((LocalDate) parameterValue));
            } else {
                throw new SQLException("Unsupported parameter type: " + parameterValue.getClass().getName());
            }
            parameterIndex++;
        }
        lastQuery += ps.toString();
        lastParameters = parameters;
    }
}
