        const animationTracksByNodeIDs = {};
        preferredAnimation.tracks.forEach(track => {
          const { node, targets } = track;
          const nodeID = node.id;
          if (!animationTracksByNodeIDs[nodeID]) {
            animationTracksByNodeIDs[nodeID] = [];
          }
          animationTracksByNodeIDs[nodeID].push(track);
        });

        // Umgang mit Animationssätzen für jedes glTF-Knotenobjekt, um die Namen zu finden
        const animationNames = {};
        scenes.forEach(scene => { // Durchlaufen jeder Szene im glTF-Objektgraphen
          scene.nodes.forEach(node => { // Durchlaufen jedes Knotenobjektes in der Szene
