   ```java
   import java.util.HashMap;
   import java.util.List;
   import java.util.Map;

   Map<String, List<String>> categories = new HashMap<>();

   String[] flowers = {"Lilac", "Daisy", "Marigold", "Chrysanthemum", "Rose", "Lavender", "Hydrangea", "Geranium"};

   for (String flower : flowers) {
       String kind = classifyFlower(flower);
       List<String> flowerList = categories.getOrDefault(kind, new ArrayList<>());
       flowerList.add(flower);
       categories.put(kind, flowerList);
