   private String classifyFlower(String flower) {
       String regularExpression = "^(\\w+)\\b"; // Matthews-Grundregel für Wortgrenzen anfänglich mit Mindestens-einer-Zeichen-Länge
       String[] parts = flower.replaceAll(regularExpression, "$1").split(" ");
       if (parts.length > 1) {
           // Mehrere Wörter, wähle erstes
