public class RemoveDivisibleByThreeNumbers {

    public static List<Integer> removeDivisibleByThreeNumbers(List<Integer> inputList) {
        List<Integer> unDivisibleList = new ArrayList<>();

        for (int I = 0; I < inputList.size(); i++) {
            int num = inputList.get(i);

            // Nummer durch 3 teilbar?
            if (num % 3 == 0) {
                // Schließe den aktuellen Eintrag aus
                continue;
            }

            // Nummer ist nicht durch 3 teilbar
            unDivisibleList.add(num);
        }

        // Alle Elemente der Eingabe sind durch 3 teilbar?
        return unDivisibleList.isEmpty() ? new ArrayList<>() : unDivisibleList;
    }

    public static void main(String[] args) {
        List<Integer> inputList = List.of(-83, -92);

        List<Integer> unDivisibleList = removeDivisibleByThreeNumbers(inputList);

        if (unDivisibleList.isEmpty()) {
            System.out.println("Alle Elemente waren durch 3 teilbar.");
        } else {
            System.out.println("Nicht durch 3 teilbare Elemente: " + unDivisibleList);
        }
    }
}
