     ```typescript
     import { Request, Response, NextFunction } from 'express';

     export function CorsMiddleware(options?: CorsOptions): CorsMiddlewareFn {
       return (req: Request, res: Response, next: NextFunction): void => {
         res.header('Access-Control-Allow-Origin', '*');
         res.header('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE');
         res.header('Access-Control-Allow-Headers', 'content-type');

         next();
       };
     }

     export interface CorsMiddlewareFn extends NextFunction {}

     export interface CorsOptions {
       origin?: string;
       methods?: string[];
       allowedHeaders?: string[];
     }
     ```

   - Hier wird eine eigene Middleware-Komponente für CORS, `CorsMiddleware`, mit ihren Optionen, Typdefinitionen und der Rückgabe eines dedizierten `NextFunction`-Typs implementiert, die dem Express.js- `NextFunction`-Typ entspricht.

2. Routenarbeit (Routing Work)

   - Typschematismus kann auch beim Definieren von Routen nützlich sein. Öffnen Sie `server.ts` und erweitern Sie die aktuelle Route wie folgt:

     ```typescript
     import express, { Request, Response } from 'express';
     import { User } from './models';

     const app = express();

     // Ein typsicherer Route-Handler für GET-Anfragen
     app.get<GetUsersHandler>('/users', getUsers);

     // Ein typsicherer Route-Handler für POST-Anfragen
     app.post<CreateUserHandler>('/users', createUser);

     // Ein typischer Route-Handler mit optionalem Antworttyp
     app.get<{ query: { id: string } }>('/users/:id', (req: Request, res: Response<User>) => {
       res.json(getUserById(req.params.id));
     });

     // Typsichere Routen mit Bedingungen
     app.get('/users',
       (req: Request, res: Response<User[]>, next: NextFunction) => {
         if (req.query.filter) {
           next();
         } else {
           res.status(400).send('Filter query parameter is required');
         }
