     );

     // Ein typsicherer Callback mit einem injizierten `User`-Typ
     function getUsers(req: Request, res: Response<User[]>): void {
       res.json(getAllUsers());
     }

     function createUser(req: Request, createUser: Express.Request<User>, res: Response<User>): void {
       const createdUser = createUserBody(req.body);
       res.json(createUserDb(createdUser));
     }

     // Ein typischer, nicht typsicherer Callback
     function getUserById(id: string): User {
       // ...
     }

     function filterUsers(req: Request, res: Response<User[]>): void {
       res.json(filterUsersByName(req.query.filter));
     }
     ```

   - Hier definieren wir Typvorlagen für die Routen, die die Typen für die Anforderungs- und Antwortobjekte sowie die Route-Handler erfordern.

