{
"books": [
{
"title": "Wer die Nachtigall stört",
"author": "Harper Lee",
"publication_date": "11.07.1960T00:00:00Z"
},
{
"title": "Der Fänger im Roggen",
"author": "J.D. Salinger",
"publication_date": "16.07.1951T00:00:00Z"
}
]
}
