            // Schritt 1 aus Websuchergebnis [[3](https://www.ccl.org/articles/leading-effectively-articles/instill-coaching-culture/)] umsetzen
            // veranschaulichen Sie den Wert einer Coaching-Kultur, indem Sie potenzielle Einflussnehmer der Möglichkeit gewähren, ihre Macht zu entfalten, ohne dass Sie von dem Wert des Coachings
            // als Führungsmethode behaupten.*

            // ...
         }

         @Test
         public void testSchritt2() throws Exception {
            // Schritt 2 aus Websuchergebnis [[3](https://www.ccl.org/articles/leading-effectively-articles/instill-coaching-culture/)] umsetzen
            // Stärken Sie das Coaching-Know-how durch verantwortungsvolle Führungspersönlichkeiten. Erziehen Sie interessierte, ranghohe Mitarbeiter, darin, ihre Bedeutung für das Coaching als Resonanzräume zu definieren.
            //  ...

            // ...
         }

