const { createRule } = require('eslint');
const { LIFECYCLE_HOOKS } = require('vue/dist/vue.common');

const createUpdateLifecycleHooksRule = () => {
  return createRule({
    name: 'my-vue-lifecycle/update-lifecycle-hooks',
    meta: {
      docs: {
        description: 'Prohibits updating lifecycle hooks or calling them passing arguments that will change the internal state',
        recommended: true,
      },
      type: 'problem',
      fixable: 'code',
      schema: [],
    },
    create(context) {
      const internalHookList = LIFECYCLE_HOOKS.filter((hook) =>
        hook.startsWith('before') || hook.startsWith('updated')
      );

      /**
       * Check method arguments to detect if a method is called with arguments that might change the internal state.
       * @param args - Method call arguments.
       * @returns {boolean} True if arguments might be problematic.
       */
      const checkMethodArguments = (args) => {
        const problematicArgs = args.filter(({ type }) =>
          internalHookList.includes(type) && ['Function', 'Object'].includes(type.kind)
        );
        return problematicArgs.length > 0;
      };

      /**
       * Check lifecycle hook methods for forbidden updates and problematic internal state change.
       * @param node - AST node representing the lifecycle hook method definition.
       */
      function checkLifecycleHook(node) {
