  rules: {
    // Schreibe Ihre Regeln hier
    'vue/no-change-state-in-lifecycle-hooks': {
      meta: {
        fixable: 'code',
        messages: {
          always: '{{methodName}} Ändert den internen Komponentenstatus direkt ({{propertyName}}) oder indirekt ({{methodWithChangedProperty}}). Lifecycle-Hooks sollten keine Änderungen an deren internen Zustand vornehmen.',
          onlyLifecycleHooks: '`{{methodName}}` ruft eine Methode auf, die den internen Komponentenstatus direkt ({{propertyName}}) oder indirekt ({{methodWithChangedProperty}}) ändern würde. Diese Änderungen sollten von Lifecycle-Hooks ausgeführt werden.',
        },
      },
      create(context) {
        const knownLifecycleHooks = ['beforeCreate', 'created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'activated', 'deactivated', 'beforeDestroy', 'destroyed'];
        const isLifecycleHook = (node) => knownLifecycleHooks.includes(node.key.value);

        return {
          // Lifecycle hooks
          LifecycleDirective hoisted (node) {
            if (!isLifecycleHook(node)) {
              return;
            }
            checkForStateChange(node.value);
          },

          // Any other method call
          CallExpression(node, state) {
            const callee = node.callee;
            if (callee.type !== 'MemberExpression' || !callee.object && !callee.object.type === 'ThisExpression') {
              return;
            }

            const methodName = callee.property.name;
            if (methodName === 'watch' || methodName === 'computed') {
              return;
            }

            checkForStateChange(node, methodName);
          },
        };

        function checkForStateChange(node, methodName = null) {
          const report = (propertyName, methodWithChangedProperty) => {
            const message = methodName ? messages.onlyLifecycleHooks : messages.always;

            context.report({
              node,
              fix(node, fixer) {
                if (!methodName) {
                  return fixer.removeRange(node.range);
                }
                const propertyNodesToIgnore = ['data', 'props', 'parent', 'attrs', 'listeners'];

                // Ignore assignment to properties defined in life-cycle hooks and props
                const propertyNodesToExclude = node.parentProperties
                  .filter(({key, value}) => {
                    const {name: propName} = key;
                    return propName !== 'this' && propName !== 'instance' && // Exclude 'this' and 'instance'
                      value && value.type === 'ObjectExpression' &&
                      propertyNodesToIgnore.every(propertyNode => !value.members.find(({key: propertyNodeKey}) => propertyNodeKey.name === propertyNode.key.name));
                  })
                  .map(({key}) => key.name);

                // Ignore method calls to properies and computed properties
                const methodCallNodesToExclude = node.parentArguments
                  .filter(argument => argument.type === 'ArrayExpression')
                  .flatMap(argument => argument.elements)
                  .filter(({object}) => object.type === 'MemberExpression' && propertyNodesToExclude.includes(object.property.name))
                  .map(({object}) => object.object);

                const fixers = [];

                // Remove the assignment
                if (methodName || node.type === 'MemberExpression') {
                  fixers.push(
                    fixer.removeRange(node.range),
                  );
                }

                // Remove method calls to properties or computed properties
                methodCallNodesToExclude.forEach(propertyOrComputedProperty => {
                  const propertyCallExpressions = node.parentArguments
                    .filter(argument => argument.type === 'ArrayExpression')
                    .flatMap(argument => argument.elements)
                    .filter(({object}) => object.type === 'MemberExpression' && object.object === propertyOrComputedProperty);

                  fixers.push(...propertyCallExpressions.map(propertyCallExpression => {
                    return fixer.removeRange(propertyCallExpression.range);
                  }));
                });

                return fixer.insertBefore(node.parent, `\n/** {{message}} */\n`, fixers);
              },
              message: methodName ? messageWithMethodName : messages.always.message,
              data: {
                methodName,
                propertyName,
                methodWithChangedProperty,
              },
            });
          };

          // Find assignment to properties which modify internal state
          node.properties.forEach((propertyNode) => {
            const {key, value} = propertyNode;

            if (value && value.type === 'ObjectExpression') {
              value.members.forEach(({key: propertyKey}) => {
                const {name: propertyName} = propertyKey;

                const propertyAssignment = value.shorthand ? propertyNode : value;

                const setterMethod = propertyAssignment.type === 'PropertyDefinition' && propertyAssignment.kind === 'init';

                if (
                  setterMethod &&
                  propertyAssignment.init &&
                  propertyAssignment.init.type === 'CallExpression' &&
                  propertyAssignment.init.callee.type === 'Identifier' &&
                  ['$set', '$delete'].includes(propertyAssignment.init.callee.name)
                ) {
                  report(propertyName);
                } else if (
                  !setterMethod &&
                  (propertyAssignment.init && propertyAssignment.init.type === 'BinaryExpression' && propertyAssignment.init.operator === '=' && /^(push|pop|shift|unshift|splice|sort|reverse)$/.test(propertyAssignment.init.left.name)) ||
                  propertyAssignment.type === 'AssignmentPattern' // Destructuring assignment
                ) {
                  report(propertyName);
                }
              });
            }
          });

          // Find method calls that modify internal state
          node.body.body.forEach((statement) => {
            if (statement.type === 'CallExpression') {
              const {callee: calledMethod} = statement;

              if (!calledMethod.object || calledMethod.object.type !== 'ThisExpression') {
                return;
              }

              const {name: methodName} = calledMethod.property;

              if (methodName === 'watch' || methodName === 'computed') {
                return;
              }

              let propertyName = '';
              let methodWithChangedProperty = '';

              const callArguments = calledMethod.arguments;
              if (callArguments.length === 0) {
                return;
              }

              const lastArgument = callArguments[callArguments.length - 1];

              if (lastArgument.type === 'MemberExpression') {
                propertyName = lastArgument.object.property.name;

                const propertyChangeMethod = lastArgument.object.object.type === 'Identifier' ? lastArgument.object.object.name : lastArgument.object.object.property.name;

                methodWithChangedProperty = `${propertyName}[${propertyChangeMethod}]`;
              } else if (lastArgument.type === 'CallExpression') {
                const {callee: propertyChangeMethod} = lastArgument;

                if (propertyChangeMethod.type === 'Identifier' && /^(push|pop|shift|unshift|splice|sort|reverse)$/.test(propertyChangeMethod.name)) {
                  propertyName = calledMethod.object.property.name;
                  methodWithChangedProperty = `${propertyName}.${propertyChangeMethod.name}()`;
                }
              }

              report(propertyName, methodWithChangedProperty);
            }
          });
        }
      },
    },
  },
};
```

### Erklärung

Die Regel  `vue-no-change-state-in-lifecycle-hooks` ist innerhalb eines Einzelmoduls exportiert und verwendet das `eslint-plugin-vue` Plug-in. Sie überprüft alle Lifecycle-Hook-Methoden (`beforeCreate`, `created`, `beforeMount`, `mounted`, `beforeUpdate`, `updated`, `activated`, `deactivated`, `beforeDestroy`, `destroyed`) sowie alle anderen Methodenaufrufe eines Komponenten-Instanzenverweises (`this`).

- First, we define two separate messages for the rule depending on the method calling context:
  - `always` when a method directly or indirectly changes the internal component state, and
  - `onlyLifecycleHooks` when this happens outside a lifecycle method, but a method is called which would modify the internal component state if invoked from within a lifecycle method.
- We then check the method calling context, whether it's a `LifecycleDirective` or an ordinary `CallExpression`.
- If the method call is within a Lifecycle Hook, we recursively check each assignment and method call (`this` reference) for valid property changes.
- If a lifecycle hook is updating properties that affect internal state, such as modifying an array, object with non-shallow updates, or a `$set`/`$delete` reactive setter call, this particular statement will trigger a warning.
- If any other method call occurs outside of a lifecycle hook that, when invoked inside a lifecycle hook, would modify internal state, trigger a warning with both the method name and the modified property path.
- Note that this rule ignores computed properties and watchers for now.

