```javascript
const { RuleTester } = require('eslint');
const { forbiddenUpdaterExpression } = require('eslint-plugin-vue/lib/utils');
const { REACTIVITY_METHODS, LIFECYCLE_HOOK_NAMES } = require('eslint-plugin-vue');

const rule = {
  meta: {
    type: 'suggestion',
    fixable: 'code',
    messages: {
      internalStateChange: `Die Methode $Name ändert den internen Status des Komponenten-Objekts und sollte nur von Lifecycle-Hook-Methoden aufgerufen werden, die von Vue automatisch ausgeführt werden.`,
      recursiveStateMutation: `Aufruf der Methode $Name aus einer anderen Methode als einer Lifecycle-Hook-Methode von Vue verändert den internen Status des Komponenten-Objekts und sollte vermieden werden.`,
    },
    docs: {
      description:
        'Warns when lifecycle hook methods assigned to the `updated` option update the internal state of the component (e.g. Calling `$set` or `this.$data.prop = ...`). Also warns when methods other than lifecycle hook methods assigned to the component are calling methods or updating properties that update the internal state of the component.',
      category: 'Best Practices',
      recommended: 'error',
    },
    schema: [],
  },

  create(context) {
    const { reporter } = context;
    const { REACTIVITY_METHODS, LIFECYCLE_HOOK_NAMES } = require('eslint-plugin-vue');

    function reportError(node, message, name) {
      const { start } = node;

      reporter.report({
        message,
        node,
        loc: start,
      });

      // ESLint 7.26.0 or later supports fixers for suggestions
      if (context.options[0] === 'error' && context.client) {
        context.report({ message, loc: start, fix: fixUpdaterExpression(node, name) });
      }
    }

    function getLocalName(node) {
      if (node.id) {
        return node.id.name;
      }
      return '';
    }

    function getNodeLoc(node) {
      const { start } = node;

      return {
        start,
        end: {
          line: start.line,
          column: start.column + node.value.length,
        },
      };
    }

    function hasStateMutation(loc, prevLoc) {
      const diff = prevLoc && prevLoc.end && prevLoc.end.line !== loc.end.line;
      const afterLastColumn = prevLoc && prevLoc.end.column > loc.start.column;

      return diff || afterLastColumn;
    }

    function pointerInside(node, pointer) {
      const { start } = node;
      return start.line <= pointer.line && start.column <= pointer.column && (
        pointer.line === start.line + 1 || // Neue Zeile nach dem letzten Charakter; Fehlt am Ende einer new-line-Endung wie Zusammenhang '\n`'
        pointer.column >= start.column + node.value.length // Auf gleicher Zeile hinter letztem Charakter des aktuellen Nodes
      );
    }

    function fixUpdaterExpression(node, name) {
      const start = getNodeLoc(node);
      const end = getNodeLoc(node.parent);
      const code = node.parent.loc.start.column + node.value;

      return (fixer) => {
        const newNode = fixer.removeRange([start.end, end.start]);
        const updateExpr = getUpdateExpr(node, name);

        if (updateExpr) {
          const newStart = getNodeLoc(updateExpr);
          const newEnd = getNodeLoc(updateExpr.parent);

          return fixer.insertBefore(newNode, newStart.start)
            .insertTextBefore(newStart, updateExpr.value, true)
            .removeRange([newEnd.end, end.start]);
        }

        return null;
      };
    }

    function getUpdateExpr({ value: updaterExpr }, name) {
      const match = forbiddenUpdaterExpression(updaterExpr);

      if (!match) {
        return null;
      }

      const [, editorRange, , methodExpr, propertyPath] = match;

      // methodExpr: `this.$data.prop = ...`
      // propertyPath: `.prop`

      const newName = `${name}Updater`;
      const mappedExpr = `('${newName}', ...${editorRange}).bind(this)`;

      const mappedMethodExpr = fixer => {
        const start = getNodeLoc(methodExpr);
        const end = getNodeLoc(methodExpr.parent);

        return fixer.replaceRange(
          editorRange,
          `{this.${methodExpr.value}}`,
          `{${newName}}`,
        )
          .insertTextBefore(start, mappedExpr);
      };

      const mappedPropertyPath = fixer => {
        const start = getNodeLoc(propertyPath);
        const end = getNodeLoc(propertyPath.parent);

        return fixer.replaceRange(propertyPath.value, methodExpr.value + propertyPath.value, newName + propertyPath.value);
      };

      return fixer.replaceTextRange([methodExpr.range[1], end.start], mappedMethodExpr)
        .replaceTextRange(editorRange, mappedPropertyPath);
    }

    function validateHooks(hooks, { stateProps }) {
      hooks.some((hook, index, hooks) => {
        const { value } = hook;

        // Es gibt keine destrukturierung für Obejekte in destructuring assignments, also kein access zu Object.keys(value)
        const hookName = Object.keys(hook)[0];
        const hookLoc = getNodeLoc(hook);

        if (LIFECYCLE_HOOK_NAMES.includes(hookName) && hasStateMutation(hookLoc, stateProps.prevLoc)) {
          reportError(hook, rule.meta.messages.internalStateChange, `${hookName}${hook.value ? ` (${hook.value})` : ''}`);
        }

        // Warnung für rekursive Komponentenstatus-Änderungen aus Methoden außer Lifecycle Hooks
        const methodLoc = getNodeLoc(value);

        if (!LIFECYCLE_HOOK_NAMES.includes(hookName) && hasStateMutation(methodLoc, stateProps.prevLoc)) {
          reportError(value, rule.meta.messages.recursiveStateMutation, `${getLocalName(value)}${value.value ? ` (${value.value})` : ''}`);
        }

        return stateProps.prevUpdated;
      });
    }

    function validateMethod(node, stateProps) {
      if (!REACTIVITY_METHODS.has(node.value)) return;

      const { start } = node;
      const prevLoc = stateProps.prevLoc || { start: start };

      if (hasStateMutation(getNodeLoc(node), prevLoc)) {
        reportError(node, rule.meta.messages.recursiveStateMutation, getLocalName(node));
      }
    }

    return {
      'ObjectExpression:exit'(node) {
        const { updated } = node.value;

        if (!updated) return;

        const { prevUpdated } = node._options || {};

        if (updated.length < 1) return;

        const stateProps = { prevLoc: prevUpdated && prevUpdated[0] && getNodeLoc(prevUpdated[0]) };

        validateHooks(updated, stateProps);
      },
      'Property:exit'(node) {
        if (node.shorthand) return;
        if (!node.value || !REACTIVITY_METHODS.has(node.value)) return;

        validateMethod(node, { prevLoc: null });
      },
    };
  },
};

module.exports = rule;
```

