     create: function(context) {
       const state = {
         // Tracks the function call chains that lead to state changes
         callingChains: new Map(),
       };

       return {
         /* eslint-enable-next-line max-statements */

         /* Process updated Lifecycle hooks */
         'VueTemplate:call-expression'(node) {
           //Skip non-method expressions, for instance, literals, properties etc.
           if (!isMethodCall(node.callee)) return;

           // Get the current method call chain
           const parentFn = getCallingFn(context, node.parent);
           let callingChain = state.callingChains.get(parentFn);
           if (!callingChain) {
             callingChain = [];
             state.callingChains.set(parentFn, callingChain);
           }

           // Append the current method call to the chain
           callingChain.push(node);

           // Check if this method, or any of its parents, alter internal component state directly or indirectly
           const altersInternalState = hasInternalStateAlteration(node, callingChain);

           // Emit warning if applicable
           if (altersInternalState) {
             context.report({
               node,
               message:
                 "Avoid altering internal component state via this method call or its indirect call chain. Note: Lifecycle hook methods should be concerned with updating internal component state outside of the method call itself.",
             });
           }
         },
       };
     },
   };

   function isMethodCall(node) {
     return (
       node.type === 'MemberExpression' &&
       node.object.type === 'Identifier' &&
       node.object.name === 'this' &&
       node.property.type === 'Identifier'
     );
   }

   function getCallingFn(context, node) {
     while (node.type !== 'MethodDefinition') {
       node = context.getAncestor(node, 'MethodDefinition');
       if (node === null) return null;
     }
     return node.key.name;
   }

   /**
    * Recursively check if the given method call chain alters internal component state directly or indirectly by calling methods that do the same
    *
    * @param {ASTNode} node - The current method call node
    * @param {Array<ASTNode>} callingChain - An array containing nodes from the current method call chain
    * @returns {boolean} - Determines whether the method call chain alters internal component state
    */
   function hasInternalStateAlteration(node, callingChain) {
     // Check if method directly alters internal component state (e.g. By calling internal methods)
     if (isDirectStateAlteration(node)) return true;

     // Traverse through all parent calls recursively, checking if any first non-method call alters internal state
     for (let I = callingChain.length - 2; I >= 0; i--) {
       const currentCall = callingChain[i];
       if (isDirectStateAlteration(currentCall)) return true;
       if (isFirstNonMethodCall(callingChain, i)) {
         if (hasInternalStateAlteration(currentCall, callingChain.slice(0, i + 1))) return true;
         break;
       }
     }

     return false;
   }

   /**
    * Detect if method directly modifies internal component state
    *
    * @param {ASTNode} node - The current method call node
    * @returns {boolean} - Determines whether the method call directly alters internal component state
    */
   function isDirectStateAlteration(node) {
     // Check if method directly alters internal component state
     const methodName = node_propertyValue(node);
     const allowedMethods = ['created', 'destroyed', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'activated', 'deactivated'];

     return (
       /\b(data|props)\b/.test(methodName) ||
       !!calledInProgressData(node) ||
       allowedMethods.includes(methodName) // special case for allowed lifecycle hook methods that don't alter state
     );
   }

   function isFirstNonMethodCall(callingChain, index) {
     const node = callingChain[index];
     return (
       !isMethodCall(node) &&
       index > 0 &&
       (!isMethodCall(callingChain[index - 1]) || isNestedMethodCall(callingChain, index))
     );
   }

   function calledInProgressData(node) {
     return (
       node.arguments.length === 1 &&
       node.arguments[0].type === 'ArrayExpression' &&
       node.arguments[0].elements.length === 1 &&
       node.arguments[0].elements[0].type === 'Identifier' &&
       node.arguments[0].elements[0].name === 'inProgressData'
     );
   }

   function isNestedMethodCall(callingChain, index) {
     const node = callingChain[index];
     const parentNode = callingChain[index - 1];

     // Handle nested method calls within another method call, e.g.: `component.method().childMethod()`
     return (
       isMethodCall(parentNode) &&
       (parentNode.callee instanceof ObjectProperty) && // Handle `.something()` syntax
       isMethodCall(node) &&
       (node.callee instanceof ObjectProperty || node.callee instanceof MemberExpression) // Handle `.something()` or `obj.something()` syntax
     );
   }

   function node_propertyValue(node) {
     if (node.property.type === 'Identifier') {
       return node_propertyValue_ident(node);
     } else if (node.property.type === 'MemberExpression') {
       return node_propertyValue_member(node);
     }
   }

   function node_propertyValue_ident(node) {
     return node.property.name;
   }

   function node_propertyValue_member(node) {
     return `${node_propertyValue_ident(node COMPUTED_property)}.${node_propertyValue_member(node)}`;
   }
